            if u != start:
                continue  # Skip to start node initially

            # Try different starting points for cycle detection
            path = [start]
            stack = [(start, -1, {start})]  # (current, parent, visited_in_path)

            while stack:
                curr, parent, visited_set = stack[-1]

                if curr in visited_set and curr != parent:
                    # Found a back-edge, construct cycle
                    cycle_idx = visited_set.index(curr)
                    cycle = [path[i] for i in range(cycle_idx, len(path) + 1)]

                    if len(cycle) >= 3 and len(cycle) % 3 != 0:
                        cycles.append(cycle)
