    n = people with 10 euro banknotes
    m = people with 20 euro banknotes  
    k = initial 10 euro banknotes Charlie has

    Total permutations: C(n+m, m)

    Using reflection principle:
    Invalid paths = C(n+m, k+1+m)  [reflection across barrier]
    """
    # Parse input
    parts = input_str.strip().split()
    n = int(parts[0])
    m = int(parts[1])
    k = int(parts[2])

    # If m=0, no one needs change, probability is 1
    if m == 0:
        return "1\n"

    # If k >= m, we can always provide change (sufficient initial 10€ notes)
    if k >= m:
        return "1\n"

    # Total number of orderings = C(n+m, m)
    total = nCr(n + m, m)

    # Number of valid orderings = Total - Invalid
    # Using reflection principle: invalid = C(n+m, m-k-1)
    # But we need to count ways to cross the "failure line"
    # Failure occurs when 20 euro people exceed k + 10 euro people by 1

    # Number of invalid paths = C(n+m, m-k-1) when m > k
    invalid = nCr(n + m, m - k - 1)

    valid = max(0, total - invalid)

    probability = valid / total

    # Format with high precision
    return f"{probability:.12f}\n"
