    omega = [0] * (max_n + 1)
    for d in range(2, int(max_n**0.5) + 2):
        if omega[d] == 0:
            for multiple in range(d, max_n + 1, d):
                omega[multiple] += 1

    # f0[n] = 2^(number of distinct prime factors)
    f0 = [0] * (max_n + 1)
    f0[1] = 1  # Handle n=1
    for n in range(2, max_n + 1):
        f0[n] = pow(2, omega[n], MOD)

    # Group queries by r for efficient iteration
    queries_by_r = defaultdict(list)
    for r, n in unique_queries:
        queries_by_r[r].append(n)

    sorted_r = sorted(queries_by_r.keys())

    results_by_r = {}
    prev_f = [f0]  # fr for r-1

    # Precompute divisors using sieve
    divisors = [[] for _ in range(max_n + 1)]
    for i in range(1, max_n + 1):
        for multiple in range(i, max_n + 1, i):
            divisors[multiple].append(i)

    # Compute fr iteratively for needed r values
    for i, r in enumerate(sorted_r):
