            results_by_r[0] = fr
        else:
            cur_fr = [0] * (max_n + 1)
            for n in range(1, max_n + 1):
                # fr[n] = sum of fr-1(d) for all divisors d|n
                for d in divisors[n]:
                    if d <= len(prev_f) - 1:
                        cur_fr[n] = (cur_fr[n] + prev_f[d]) % MOD if prev_f[d] >= 0 else cur_fr[n]
            results_by_r[r] = cur_fr
            prev_f = cur_fr

