def solution(input_str):
    lines = input_str.strip().split('\n')
    parts = lines[0].split()
    m, t, s = int(parts[0]), int(parts[1]), int(parts[2])

    a = list(map(int, lines[1].split()))
    MOD = 1051131

    # Generate remaining a_i if needed
    for i in range(s, 2*m):
        a.append((101 * a[i-s] + 10007) % MOD)

    n = 2 * m

    def mat_mul(A, B):
        """Matrix multiplication modulo MOD"""
        C = [[0] * n for _ in range(n)]
        for i in range(n):
            for k in range(n):
                if A[i][k] == 0:
                    continue
                for j in range(n):
                    C[i][j] = (C[i][j] + A[i][k] * B[k][j]) % MOD
        return C

    def mat_pow(A, p):
        """Matrix exponentiation"""
        result = [[0] * n for _ in range(n)]
        for i in range(n):
            result[i][i] = 1
        base = [row[:] for row in A]
        while p > 0:
            if p % 2 == 1:
                result = mat_mul(result, base)
            base = mat_mul(base, base)
            p //= 2
        return result

    def bit_count(x):
        return bin(x).count('1')

    def gcd(a, b):
        while b:
            a, b = b, a % b
        return a

    # Build transition matrix
    # M[i][j] = 1 if i==j (stay), else 2^bitcount(gcd(island_i+1, island_j+1))
    M = [[0] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            if i == j:
                M[i][j] = 1
            else:
                g = gcd(i + 1, j + 1)
                M[i][j] = (1 << bit_count(g)) % MOD

    # Compute M^t
    Mt = mat_pow(M, t)

    # Compute V_t = V_0 * Mt where V_0 = [a[0], a[1], ..., a[n-1]]
    ans = [0] * n
    for j in range(n):
        sump = 0
        for i in range(n):
            sump = (sump + a[i] * Mt[i][j]) % MOD
        ans[j] = sump

    # Compute XOR sum of all answers
    xor_sum = 0
    for x in ans:
        xor_sum ^= x

    return str(xor_sum) + '\n'
