            return float('inf'), float('inf')
        c2, c5 = 0, 0
        temp = num
        while temp % 2 == 0:
            c2 += 1
            temp //= 2
        while temp % 5 == 0:
            c5 += 1
            temp //= 5
        return c2, c5

    INF = float('inf')

    # dp[i][j] = {c5: c2} - minimum 2s count for each 5s count at cell (i,j)
    # parent[i][j][c5] = 'L' if came from left (path ended with R), 'U' if came from up (path ended with D)
    dp = [[{} for _ in range(n)] for _ in range(n)]
    parent = [[{} for _ in range(n)] for _ in range(n)]

    c2_start, c5_start = count_factors(matrix[0][0])
    dp[0][0][c5_start] = c2_start

    for i in range(n):
        for j in range(n):
            if i == 0 and j == 0:
                continue

            c2_cell, c5_cell = count_factors(matrix[i][j])
            best = {}
            best_parent = {}

            # From left (path extends with 'R')
            if j > 0:
                for c5_prev, c2_prev in dp[i][j-1].items():
                    c5_new = c5_prev + c5_cell
                    c2_new = c2_prev + c2_cell
                    if c5_new not in best or c2_new < best[c5_new]:
                        best[c5_new] = c2_new
                        best_parent[c5_new] = 'L'
                    elif c2_new == best[c5_new]:
                        # Keep existing (left would have been processed first, so up is lexicographically smaller)
                        pass

            # From above (path extends with 'D') - only if not better left option
            if i > 0:
                for c5_prev, c2_prev in dp[i-1][j].items():
                    c5_new = c5_prev + c5_cell
                    c2_new = c2_prev + c2_cell
                    if c5_new not in best or c2_new < best[c5_new]:
                        best[c5_new] = c2_new
                        best_parent[c5_new] = 'U'
                    elif c2_new == best[c5_new]:
                        # Compare with existing parent choice
                        pass

            dp[i][j] = best
            parent[i][j] = best_parent

    # Find best state at destination
    min_zeros = INF
    ans_path = ""

    for c5, c2 in dp[n-1][n-1].items():
        zeros = min(c2, c5)
        if zeros < min_zeros:
            min_zeros = zeros
            ans_path = []
            c = (n-1, n-1)
            while c != (0, 0):
                r, col = c
                p = parent[r][col].get(c5)
                if p == 'U':
                    ans_path.append('D')
                    c = (r - 1, col)
                elif p == 'L':
                    ans_path.append('R')
                    c = (r, col - 1)
                else:
