def solution(input_str):
    import sys
    sys.setrecursionlimit(20000)

    # Parse input
    lines = input_str.strip().split('\n')
    if not lines:
        return '0'

    n, b = map(int, lines[0].split())

    c = [0] * (n + 1)
    d = [0] * (n + 1)
    parent = [0] * (n + 1)

    for i in range(1, n + 1):
        parts = lines[i].split()
        c[i] = int(parts[0])
        d[i] = int(parts[1])
        if i >= 2:
            parent[i] = int(parts[2])

    # Build tree
    adj = [[] for _ in range(n + 1)]
    for i in range(2, n + 1):
        adj[parent[i]].append(i)

    INF = float('inf')

    def compute(u):
        # dp0[k] = min cost to buy k items from subtree u, u's coupon NOT needed
        # dp1[k] = min cost to buy k items from subtree u, u's coupon IS needed (discount available)

        dp0 = [0, c[u]]
        dp1 = [INF, c[u] - d[u]]
        size = 1

        for v in adj[u]:
            v_dp0, v_dp1, v_size = compute(v)

            new_dp0 = [INF] * (size + v_size)
            new_dp1 = [INF] * (size + v_size)

            for i in range(size + 1):
                for j in range(v_size + 1):
                    if i + j > size + v_size:
                        break

                    # Merge without u's coupon being required
                    if dp0[i] != INF and v_dp0[j] != INF:
                        new_dp0[i + j] = min(new_dp0[i + j], dp0[i] + v_dp0[j])

                    # Merge with u's coupon being used
                    if dp1[i] != INF and v_dp1[j] != INF:
                        new_dp1[i + j] = min(new_dp1[i + j], dp1[i] + v_dp1[j])

            size += v_size
            dp0 = new_dp0
            dp1 = new_dp1

        return dp0, dp1, size

    dp0, dp1, _ = compute(1)

    # Find maximum items within budget
    ans = 0
    for k in range(len(dp0)):
        if dp0[k] <= b:
            ans = max(ans, k)

    return str(ans)
